description:
Implement a `useKeyPress` hook that returns `true` while a specific key is held down and `false` otherwise. It should listen to `keydown` to set true and `keyup` to set false.

**Example:**
```tsx
const isEnterPressed = useKeyPress('Enter');
const isEscPressed = useKeyPress('Escape');
```

starter_code:
import { useEffect, useState } from 'react';

export function useKeyPress(targetKey: string): boolean {
  // your code here
}

test_suite:
test('returns false initially', () => {
  const { result } = renderHook(() => useKeyPress('Enter'));
  expect(result.current).toBe(false);
});

test('returns true when target key is pressed', () => {
  const { result } = renderHook(() => useKeyPress('Enter'));
  act(() => window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter' })));
  expect(result.current).toBe(true);
});

test('returns false after key is released', () => {
  const { result } = renderHook(() => useKeyPress('Enter'));
  act(() => window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter' })));
  act(() => window.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter' })));
  expect(result.current).toBe(false);
});

test('does not trigger for a different key', () => {
  const { result } = renderHook(() => useKeyPress('Enter'));
  act(() => window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' })));
  expect(result.current).toBe(false);
});

// __hidden__
test('removes listeners on unmount', () => {
  const { result, unmount } = renderHook(() => useKeyPress('a'));
  unmount();
  act(() => window.dispatchEvent(new KeyboardEvent('keydown', { key: 'a' })));
  expect(result.current).toBe(false);
});

solution:
import { useEffect, useState } from 'react';

export function useKeyPress(targetKey: string): boolean {
  const [pressed, setPressed] = useState(false);

  useEffect(() => {
    const onDown = (e: KeyboardEvent) => { if (e.key === targetKey) setPressed(true); };
    const onUp = (e: KeyboardEvent) => { if (e.key === targetKey) setPressed(false); };
    window.addEventListener('keydown', onDown);
    window.addEventListener('keyup', onUp);
    return () => {
      window.removeEventListener('keydown', onDown);
      window.removeEventListener('keyup', onUp);
    };
  }, [targetKey]);

  return pressed;
}
